window.addEventListener('message', (event) => {
    if (event.origin !== location.origin || !event.data?.type?.startsWith('skillspot:lesson-')) return;
    if (event.data.type === 'skillspot:lesson-created') {
        const addLink = document.querySelector(`a[href*="/sections/${event.data.sectionId}/lessons/create"]`);
        const chapter = addLink?.closest('.cw-card');
        if (chapter && !chapter.querySelector(`[data-edit*="/lessons/${event.data.lessonId}/edit"]`)) {
            chapter.querySelector('p')?.remove();
            const button = document.createElement('button');
            button.type = 'button';
            button.className = 'lesson-select flex w-full gap-2 border-b px-3 py-2 text-left text-xs';
            button.dataset.title = event.data.title;
            button.dataset.type = 'Text';
            button.dataset.edit = `/admin/courses/{{$course->id}}/sections/${event.data.sectionId}/lessons/${event.data.lessonId}/edit`;
            const icon = document.createElement('i');
            icon.className = 'fa-solid fa-file-lines';
            const label = document.createElement('span');
            label.className = 'flex-1';
            label.textContent = event.data.title;
            button.append(icon, label);
            button.onclick = () => openLessonInWorkspace(button.dataset.edit);
            chapter.append(button);
        }
        return;
    }
    const button = [...document.querySelectorAll('.lesson-select')].find(item => item.dataset.edit?.includes(`/lessons/${event.data.lessonId}/edit`));
